const input = $input.first().json;
const submissionPageId = input.id || '';

// Accept both orchestrator-mapped field names and raw Notion field names.
const clientName = input.client_name || input['Client'] || '';

function extractDateString(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    return v.start || v.date?.start || v.value || '';
  }
  return String(v);
}
let batchDateRaw = extractDateString(input.batch_date) || extractDateString(input['Week Of']);
let batchDate = batchDateRaw ? batchDateRaw.substring(0, 10) : DateTime.now().toFormat('yyyy-MM-dd');
if (!/^\d{4}-\d{2}-\d{2}$/.test(batchDate)) {
  const parsed = new Date(batchDateRaw);
  batchDate = isNaN(parsed.getTime()) ? DateTime.now().toFormat('yyyy-MM-dd') : parsed.toISOString().substring(0, 10);
}

const notesRaw = (input.notes_for_ai || input['Notes for AI'] || '').trim();
const callNumberOverride = input.call_number_override || null;

// NEW (Phase 1a): explicit-source model
// Sources is a multi-select. Look it up case-insensitively across common name variants.
function findInputField(obj, candidates) {
  if (!obj) return null;
  const entries = Object.entries(obj);
  for (const c of candidates) {
    // exact match first
    if (obj[c] != null) return obj[c];
    // case- and whitespace-insensitive match — Notion property names sometimes carry trailing spaces
    const target = c.toLowerCase().trim();
    for (const [key, val] of entries) {
      if (key.toLowerCase().trim() === target && val != null) return val;
    }
  }
  return null;
}

const sourcesRaw = findInputField(input, ['Sources', 'Source', 'sources', 'source']);
const sources = Array.isArray(sourcesRaw) ? sourcesRaw : (sourcesRaw ? [sourcesRaw] : []);

const callTranscriptDetails = (findInputField(input, [
  'Which call(s) should we ideate from?',
  'Call Transcript Details',
  'Call Transcript',
  'call_transcript_details',
  'call_transcript'
]) || '').toString().trim();

// Capture all 6 non-Call-Transcript source detail fields (Phase 2+ uses these; Phase 1 just stores them).
const performanceReportDetails = (findInputField(input, [
  'Which performance reports should we factor in?',
  'What from the latest performance report should we focus on?',
  'Performance Report Details', 'Performance Report'
]) || '').toString().trim();
const webSearchDetails = (findInputField(input, [
  'What should the AI search the web for?',
  'Web Search Details', 'Web Search'
]) || '').toString().trim();
const slackDetails = (findInputField(input, [
  "What context from the client's Slack channel should we consider?",
  'Slack Details', 'Slack'
]) || '').toString().trim();
const competitorTrackerDetails = (findInputField(input, [
  'Which competitor activity should we react to?',
  'Competitor Tracker Details', 'Competitor Tracker'
]) || '').toString().trim();
const timelyEventsDetails = (findInputField(input, [
  'Which timely events should the ideas tie into?',
  'Timely Events Tracker Details', 'Timely Events Tracker'
]) || '').toString().trim();
const sourceRepositoryDetails = (findInputField(input, [
  'Which items from the Source Repository should we use?',
  'Source Repository Details', 'Source Repository'
]) || '').toString().trim();

// Diagnostic log: print all top-level keys so we can see exactly what the webhook delivered
console.log('Pre-process input keys: [' + Object.keys(input).join(', ') + ']');
console.log('Sources detected: ' + JSON.stringify(sources) + '. CallTranscriptDetails length: ' + callTranscriptDetails.length);

// Validate: Sources is mandatory
if (sources.length === 0) {
  throw new Error(
    'Sources is required but the webhook payload did not include a Sources field.\n' +
    'Available fields in this submission: ' + Object.keys(input).join(', ') + '.\n' +
    'Fix: in Notion, make sure the Ideation Launcher database has a multi-select property literally named "Sources", that the strategist selected at least one option, and that the Notion automation sending the webhook has been saved AFTER the field was added (re-open and save the automation to refresh its property snapshot).'
  );
}

// Phase 1a: only Call Transcript is supported for now
const supportedSources = new Set(['Call Transcript']);
const unsupported = sources.filter(s => !supportedSources.has(s));
if (unsupported.length > 0 && !sources.some(s => supportedSources.has(s))) {
  throw new Error('None of the selected sources are supported yet. Phase 1 supports: Call Transcript. Selected: ' + sources.join(', '));
}

// Parse Grain URLs from Call Transcript Details
const grainUrlPattern = /https?:\/\/(?:grain\.com|app\.grain\.com)\/(?:share\/recording|recordings?)\/([a-zA-Z0-9_-]+)/gi;
const grainUrlsFromDetails = [];
let m;
while ((m = grainUrlPattern.exec(callTranscriptDetails)) !== null) {
  grainUrlsFromDetails.push({ url: m[0], grain_recording_id: m[1] });
}

// If Call Transcript is selected but no URL is provided, fall back to auto-pick
// (Cross-check Dates uses the client's most-recent Grain call when specific_call_ref is null).
// Explicit URL is an override, not a requirement.
const callTranscriptSelected = sources.includes('Call Transcript');
if (callTranscriptSelected && grainUrlsFromDetails.length === 0) {
  console.log('Call Transcript selected without a specific Grain URL - falling back to auto-pick (most recent client call).');
}

// For Phase 1a, use the FIRST Grain URL as the explicit call.
// Phase 1b will add multi-URL support via SplitInBatches.
let specificCallRef = null;
if (grainUrlsFromDetails.length > 0) {
  specificCallRef = {
    type: 'grain_url',
    grain_recording_id: grainUrlsFromDetails[0].grain_recording_id,
    original_url: grainUrlsFromDetails[0].url,
    source_field: 'Call Transcript Details'
  };
  if (grainUrlsFromDetails.length > 1) {
    console.log('Note: multi-URL support is Phase 1b. ' + grainUrlsFromDetails.length + ' URLs were pasted; using only the first (' + grainUrlsFromDetails[0].grain_recording_id + ') for this run.');
  }
}

// Legacy: also check Notes for AI for a Grain URL (back-compat for older submissions)
if (!specificCallRef) {
  const legacyMatch = notesRaw.match(/https?:\/\/(?:grain\.com|app\.grain\.com)\/(?:share\/recording|recordings?)\/([a-zA-Z0-9_-]+)/i);
  if (legacyMatch) {
    specificCallRef = {
      type: 'grain_url',
      grain_recording_id: legacyMatch[1],
      original_url: legacyMatch[0],
      source_field: 'Notes for AI (legacy)'
    };
  }
}

// Compute call sign and clean name (still used for batch naming)
const cleanName = clientName.replace(/\s*\(.*?\)\s*/g, '').trim();
const callSign  = cleanName.split(/\s+/).filter(w => /^[A-Z]/.test(w)).map(w => w[0]).join('');

// Combine notes_for_ai with any non-URL text from Call Transcript Details
const detailsWithoutUrls = callTranscriptDetails.replace(grainUrlPattern, '').trim();
const combinedNotes = [notesRaw, detailsWithoutUrls]
  .filter(s => s && s.length > 0)
  .join('\n\n');

console.log('Pre-process: client=' + clientName + ', sources=[' + sources.join(', ') + '], grain_url_count=' + grainUrlsFromDetails.length + ', specific_call=' + (specificCallRef ? specificCallRef.grain_recording_id : '(none)'));

return [{
  json: {
    submission_page_id: submissionPageId,
    client_name: clientName,
    batch_date: batchDate,
    notes_for_ai: combinedNotes,
    sources: sources,
    call_transcript_urls: grainUrlsFromDetails,
    call_transcript_details_text: callTranscriptDetails,
    specific_call_ref: specificCallRef,
    call_number_override: callNumberOverride,
    call_sign: callSign,
    clean_client_name: cleanName,
    submitted_by_email: (input['Submitted By'] && input['Submitted By'][0]) || '',
    // Phase 2+ source details — captured now so they flow through workflow state.
    performance_report_details: performanceReportDetails,
    web_search_details: webSearchDetails,
    slack_details: slackDetails,
    competitor_tracker_details: competitorTrackerDetails,
    timely_events_details: timelyEventsDetails,
    source_repository_details: sourceRepositoryDetails,
  }
}];

const notionResult = $input.first().json;
const preprocess = $('Pre-process Inputs').first().json;

if (!notionResult.results || notionResult.results.length === 0) {
  throw new Error('No client dashboard found for: ' + preprocess.client_name + '. Check the client name matches exactly in Notion.');
}

const dashboard = notionResult.results[0];
const props = dashboard.properties || {};

// Read a Notion property as plain text, regardless of its type.
function readText(p) {
  if (!p) return '';
  if (typeof p === 'string') return p;
  if (p.rich_text?.[0]?.plain_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.title?.[0]?.plain_text)     return p.title.map(t => t.plain_text).join('');
  if (p.email)                      return p.email;
  if (p.url)                        return p.url;
  if (p.phone_number)               return p.phone_number;
  if (p.select?.name)               return p.select.name;
  if (p.formula?.string)            return p.formula.string;
  if (p.rollup?.string)             return p.rollup.string;
  if (typeof p.number === 'number') return String(p.number);
  return '';
}

const primaryEmail       = readText(props['Primary Email']);
const secondaryEmail     = readText(props['Secondary Email']);
const callSignFromNotion = readText(props['Call Sign']);
const grainSearchName    = readText(props['Grain ID']);
const grainRecordingId   = readText(props['Grain Recording ID']);

return [{
  json: {
    ...preprocess,
    dashboard_page_id: dashboard.id,
    primary_email: primaryEmail,
    secondary_email: secondaryEmail,
    call_sign_override: callSignFromNotion,
    grain_search_name: grainSearchName,
    grain_recording_id: grainRecordingId
  }
}];

const preprocess    = $('Pre-process Inputs').first().json   || {};
const dashboardInfo = $('Extract Dashboard Info').first().json || {};

// Navigation callout (Column 0) — holds the client's databases plus a "Resources" child_page.
const navBlocks = $('Fetch Navigation Callout Content').first().json?.results || [];

// General Pages callout (inside the Resources child_page) — holds the per-client docs:
// Intelligence Brief, Content Strategy Doc, Brand Config, Onboarding Forms, Competitor Tracking.
const generalBlocks = $('Fetch General Pages Callout Content').first().json?.results || [];

let callAgendasId = null;
let masterContentId = null;
let performanceReportsId = null;
let intelBriefPageId = null;
let strategyDocPageId = null;
let brandConfigPageId = null;
let competitorTrackingPageId = null;
let formatBankId = null;

function blockTitle(b) {
  if (b.type === 'child_database') return (b.child_database?.title || '').toLowerCase();
  if (b.type === 'child_page')     return (b.child_page?.title     || '').toLowerCase();
  return '';
}

for (const b of navBlocks) {
  const title = blockTitle(b);
  if (b.type === 'child_database') {
    if (title.includes('call agenda'))         callAgendasId        = b.id;
    if (title.includes('master content'))      masterContentId      = b.id;
    if (title.includes('performance report'))  performanceReportsId = b.id;
    if (title.includes('format bank'))         formatBankId         = b.id;
  }
}

for (const b of generalBlocks) {
  const title = blockTitle(b);
  if (b.type === 'child_page') {
    if (title.includes('intelligence brief'))  intelBriefPageId         = b.id;
    if (title.includes('content strategy'))    strategyDocPageId        = b.id;
    if (title.includes('brand config'))        brandConfigPageId        = b.id;
    if (title.includes('competitor tracking')) competitorTrackingPageId = b.id;
  }
}

const summarize = (arr) => arr.map(b =>
  `${b.type}: "${b.child_database?.title || b.child_page?.title || '(no title)'}" [${b.id}]`
).join(' | ');

const clientName = preprocess.client_name || dashboardInfo.client_name || '';
console.log(`Extract Client DB IDs for "${clientName}"`);
console.log(`Nav callout blocks: ${summarize(navBlocks)}`);
console.log(`General Pages blocks: ${summarize(generalBlocks)}`);

if (!callAgendasId)    throw new Error(`Could not find 'Call Agendas' database for ${clientName}. Nav callout: ${summarize(navBlocks)}`);
if (!masterContentId)  throw new Error(`Could not find 'Master Content Database' for ${clientName}. Nav callout: ${summarize(navBlocks)}`);
if (!intelBriefPageId) throw new Error(`Could not find 'Intelligence Brief' page for ${clientName} inside Resources → General Pages. General Pages: ${summarize(generalBlocks)}`);
// strategy_doc_page_id deprecated in v71+ — content baked into Intel Brief

return [{
  json: {
    ...preprocess,
    ...dashboardInfo,
    client_name: clientName,
    call_agendas_db_id: callAgendasId,
    master_content_db_id: masterContentId,
    performance_reports_db_id: performanceReportsId,
    format_bank_db_id: formatBankId,
    intel_brief_page_id: intelBriefPageId,
    strategy_doc_page_id: strategyDocPageId,
    brand_config_page_id: brandConfigPageId,
    competitor_tracking_page_id: competitorTrackingPageId
  }
}];

const input = $input.first().json;
const intelBriefText = input.intel_brief_text || '';

// --- Parse §2 Posting Cadence table from the intel brief ---
// The serialized table rows look like:
//   | Platform | Total/Batch | Long Form | Short Form | LF Days | SF Days | Posts/Day | Time | Timezone |
//   | LinkedIn | 7 | ...
//   | X | 14 | ...
function parseTableRow(text, platformName) {
  const lines = text.split('\n');
  const rx = new RegExp('^\\|\\s*' + platformName + '\\s*\\|', 'i');
  for (const line of lines) {
    if (rx.test(line.trim())) {
      const cells = line.split('|').map(c => c.trim()).filter((_, i, arr) => i > 0 && i < arr.length - 1);
      return cells;  // [platform, total_per_batch, long_form, short_form, lf_days, sf_days, posts_per_day, time, timezone]
    }
  }
  return null;
}

const liRow = parseTableRow(intelBriefText, 'LinkedIn');
const xRow  = parseTableRow(intelBriefText, 'X');

function intOrZero(s) { const n = parseInt((s || '').replace(/[^0-9-]/g, ''), 10); return isNaN(n) ? 0 : n; }

let linkedinPosts = liRow ? intOrZero(liRow[1]) : 0;
let xPosts        = xRow  ? intOrZero(xRow[1])  : 0;

// Fallback: if §2 wasn't parseable, try a generic regex on the whole brief
if (!linkedinPosts && !xPosts) {
  const liMatch = intelBriefText.match(/linkedin[:\s]+([0-9]+)/i);
  const xMatch  = intelBriefText.match(/(?:^|\s)x(?:\/twitter)?[:\s]+([0-9]+)/i);
  linkedinPosts = liMatch ? parseInt(liMatch[1]) : 7;
  xPosts        = xMatch  ? parseInt(xMatch[1])  : 14;
}

const BUFFER = 3;
const sharedCount = (linkedinPosts > 0 && xPosts > 0) ? Math.min(linkedinPosts, xPosts) : 0;
const linkedinOnlyCount = (xPosts > 0) ? Math.max(0, linkedinPosts - sharedCount) : linkedinPosts;
const xOnlyCount = (linkedinPosts > 0) ? Math.max(0, xPosts - sharedCount) : xPosts;
const effectiveQuota = Math.max(linkedinPosts, xPosts) + BUFFER;
const transcriptQuota = effectiveQuota;
const totalPostsPerBatch = linkedinPosts + xPosts;

// --- AM name parser (unchanged from v70) ---
function parseAmName(text) {
  const cleanName = (s) => (s || '').replace(/[\(\)\*_`"]/g, '').trim().split(/\s{2,}|\t/)[0].trim();
  const patterns = [
    /Strategist\s*\/\s*AM\s*[:\-]\s*([^\n,;\|]+)/i,
    /Strategist\s*\/\s*AM\s*\n\s*([^\n,;\|]+)/i,
    /Account\s*Manager\s*[:\-]\s*([^\n,;\|]+)/i,
    /Account\s*Manager\s*\n\s*([^\n,;\|]+)/i,
    /\bStrategist\s*[:\-]\s*([^\n,;\|]+)/i,
    /\bAM\s*[:\-]\s*([^\n,;\|]+)/i
  ];
  for (const rx of patterns) {
    const m = text.match(rx);
    if (m && m[1]) {
      const name = cleanName(m[1]);
      if (name && name.length < 80 && !/^(none|n\/a|tbd|tbc|unknown)$/i.test(name)) return name;
    }
  }
  return '';
}
const amName = parseAmName(intelBriefText);
const hasMiscPillar = /miscellaneous/i.test(intelBriefText);

console.log('Cadence: LI=' + linkedinPosts + ', X=' + xPosts + ' -> shared=' + sharedCount + ', LI-only=' + linkedinOnlyCount + ', X-only=' + xOnlyCount + ', buffer=' + BUFFER + ', effective_quota=' + effectiveQuota);
console.log('Strategist / AM detected: "' + (amName || '(NONE)') + '"');
console.log('Intel brief chars total: ' + intelBriefText.length);

return [{
  json: {
    ...input,
    intel_brief_text: intelBriefText,
    total_posts_per_batch: totalPostsPerBatch,
    linkedin_posts: linkedinPosts,
    x_posts: xPosts,
    effective_quota: effectiveQuota,
    shared_count: sharedCount,
    linkedin_only_count: linkedinOnlyCount,
    x_only_count: xOnlyCount,
    buffer_count: BUFFER,
    transcript_idea_quota: transcriptQuota,
    has_misc_pillar: hasMiscPillar,
    am_name: amName
  }
}];

const allItems = $input.all();
const contextData = $('Extract Context and Calculate Quota').first().json;
const preprocess = $('Pre-process Inputs').first().json || {};

const grainRaw = allItems[0]?.json;
const notionRaw = allItems[1]?.json;

const clientName = preprocess.client_name || contextData.client_name || '';
const callSign = contextData.call_sign_override || preprocess.call_sign_override || preprocess.call_sign || contextData.call_sign || '';
const primaryEmail   = (contextData.primary_email   || '').toLowerCase().trim();
const secondaryEmail = (contextData.secondary_email || '').toLowerCase().trim();

const allRecordings = (grainRaw?.recordings || []).filter(c => !!c?.id);
const notionRows = notionRaw?.results || [];
const allRows = notionRows;

const callNumberOverride = parseInt(preprocess.call_number_override, 10);

const MIN_DURATION_SEC = 600;

function pickRecordingDate(r) {
  if (!r) return '';
  const candidates = [r.start_datetime, r.started_at, r.recorded_at, r.meeting_start_at, r.meeting_started_at, r.record_started_at, r.created_at];
  for (const c of candidates) {
    if (c == null || c === '') continue;
    if (typeof c === 'number') return new Date(c * (c < 1e12 ? 1000 : 1)).toISOString();
    if (typeof c === 'string') return c;
  }
  return '';
}
function recordingDurationSec(r) {
  if (typeof r?.duration === 'number') return r.duration;
  if (typeof r?.duration_seconds === 'number') return r.duration_seconds;
  const start = pickRecordingDate(r);
  const end = r?.end_datetime || r?.ended_at || r?.meeting_end_at || '';
  if (start && end) {
    const s = new Date(start).getTime();
    const e = new Date(end).getTime();
    if (!isNaN(s) && !isNaN(e) && e > s) return Math.round((e - s) / 1000);
  }
  return 0;
}
function rowCallTitle(row) {
  const props = row?.properties || {};
  for (const [, v] of Object.entries(props)) {
    if (v?.type === 'title') {
      const t = (v.title || []).map(rt => rt?.plain_text || '').join('');
      if (t) return t;
    }
  }
  return '';
}
function rowCallNumber(row) {
  const m = (rowCallTitle(row) || '').match(/Call\s+(\d+)/i);
  return m ? parseInt(m[1], 10) : 0;
}
function rowCallDate(row) { return row?.properties?.['Call Date']?.date?.start || ''; }
function rowTranscriptUrl(row) {
  return row?.properties?.['Transcript URL']?.url || row?.properties?.['Transcript Doc']?.url
    || row?.properties?.['Transcript Link']?.url || row?.properties?.['Transcript']?.url || '';
}
function rowGrainIdText(row) {
  return row?.properties?.['Grain Recording ID']?.rich_text?.[0]?.plain_text
    || row?.properties?.['Grain ID']?.rich_text?.[0]?.plain_text || '';
}
function rowContainsGrainId(row, grainId) {
  if (!grainId) return false;
  for (const [, v] of Object.entries(row?.properties || {})) {
    if (!v) continue;
    if (v.type === 'url' && v.url && v.url.includes(grainId)) return true;
    if (v.type === 'rich_text') { const t = (v.rich_text || []).map(rt => rt?.plain_text || '').join(''); if (t.includes(grainId)) return true; }
    if (v.type === 'title') { const t = (v.title || []).map(rt => rt?.plain_text || '').join(''); if (t.includes(grainId)) return true; }
  }
  return false;
}
function findRowByGrainId(grainId) {
  return notionRows.find(r => rowGrainIdText(r) === grainId || rowContainsGrainId(r, grainId));
}

const maxCallNumber = allRows.reduce((max, r) => Math.max(max, rowCallNumber(r)), 0);
const nextCallNumber = maxCallNumber + 1;
console.log(`Call Agendas has ${allRows.length} row(s), max parsed Call N = ${maxCallNumber}, next would be Call ${nextCallNumber}.`);

if (!clientName) return [{ json: { ...contextData, abort: true, abort_reason: 'client_name is empty.' } }];

function buildFallbackList(allClientCalls, primaryId) {
  // Use ALL email-matched client calls (not just substantive) so we always have alternatives
  // when the primary fails. The 10-min duration filter only applies to the primary pick.
  const sorted = [...allClientCalls].sort((a, b) =>
    new Date(pickRecordingDate(b) || 0) - new Date(pickRecordingDate(a) || 0)
  );
  return sorted
    .filter(r => r.id !== primaryId)
    .slice(0, 5)
    .map(r => ({
      id: r.id,
      title: r.title || ('Recording ' + r.id),
      date: pickRecordingDate(r),
      duration_sec: recordingDurationSec(r)
    }));
}

function reuseExistingRow(row, grainIdHint, source, fallbackCandidates) {
  const transcriptUrl = rowTranscriptUrl(row);
  const existingNum = rowCallNumber(row);
  const storedGrainId = rowGrainIdText(row) || grainIdHint || '';
  console.log(`Reusing existing Call Agendas row "${rowCallTitle(row)}" via ${source}. Has transcript: ${!!transcriptUrl}. ${fallbackCandidates.length} fallback(s) available.`);
  return [{
    json: {
      ...contextData, abort: false,
      client_name: clientName, call_sign: callSign,
      batch_date: preprocess.batch_date || contextData.batch_date || '',
      agenda_row_id: row.id,
      transcript_doc_url: transcriptUrl,
      call_title: rowCallTitle(row) || 'Untitled Call',
      latest_grain_call_id: storedGrainId,
      latest_grain_call_date: rowCallDate(row),
      new_call_number: callNumberOverride > 0 ? callNumberOverride : (existingNum || nextCallNumber),
      use_existing_transcript: !!transcriptUrl,
      used_prev_week: false,
      selection_source: source,
      fallback_candidates: fallbackCandidates
    }
  }];
}

function emitGrainPick(pick, existing, sourceLabel, fallbackCandidates) {
  const pickedDate = pickRecordingDate(pick);
  console.log(`${sourceLabel} pick: id=${pick.id}, title="${pick.title || ''}", date=${pickedDate}, duration_sec=${recordingDurationSec(pick)}, ${fallbackCandidates.length} fallback(s).`);
  return [{
    json: {
      ...contextData, abort: false,
      client_name: clientName, call_sign: callSign,
      batch_date: preprocess.batch_date || contextData.batch_date || '',
      latest_grain_call_id: pick.id,
      latest_grain_call_title: pick.title || '',
      latest_grain_call_date: pickedDate,
      new_call_number: callNumberOverride > 0 ? callNumberOverride : nextCallNumber,
      existing_agenda_row_id: existing ? existing.id : null,
      use_existing_transcript: false,
      used_prev_week: false,
      selection_source: sourceLabel,
      fallback_candidates: fallbackCandidates
    }
  }];
}

// Path 1: Notes override
const notesGrainId = preprocess.specific_call_ref?.type === 'grain_url' ? preprocess.specific_call_ref.grain_recording_id : null;
const dashboardGrainId = contextData.grain_recording_id || '';
const overrideRecordingId = notesGrainId || dashboardGrainId;

if (overrideRecordingId) {
  // For explicit override, no fallbacks — the user picked this specific call.
  const existing = findRowByGrainId(overrideRecordingId);
  if (existing && rowTranscriptUrl(existing)) return reuseExistingRow(existing, overrideRecordingId, 'notes_override_matched_existing', []);
  const specificRec = allRecordings.find(r => r.id === overrideRecordingId);
  if (specificRec) return emitGrainPick(specificRec, existing, 'notes_override', []);
  return [{ json: { ...contextData, abort: false, client_name: clientName, call_sign: callSign,
    batch_date: preprocess.batch_date || contextData.batch_date || '',
    latest_grain_call_id: overrideRecordingId, latest_grain_call_title: 'Recording ' + overrideRecordingId, latest_grain_call_date: '',
    new_call_number: callNumberOverride > 0 ? callNumberOverride : nextCallNumber,
    existing_agenda_row_id: existing ? existing.id : null,
    use_existing_transcript: false, used_prev_week: false, selection_source: 'notes_override_id_only',
    fallback_candidates: [] } }];
}

// Path 2: Most recent substantive client call
if (!primaryEmail && !secondaryEmail) {
